// ---- Mars Life Line style header (generated by scripts/kiln-style-sync.mjs from src/style/tokens.json, style v2) ----
// Paste at the top of every .kiln.js source. Do not edit colours here; edit tokens.json and re-run npm run style:sync.
const PALETTE = {
  'space-deep': 0x20283D,
  'shadow-plum': 0x765768,
  'regolith-mid': 0xB95C40,
  'regolith-light': 0xE6A26A,
  'structure-white': 0xF2E5D2,
  'structure-gray': 0x686976,
  'trim-dark': 0x303240,
  'accent-orange': 0xFF8A24,
  'accent-cyan': 0x54E5F5,
  'accent-blue': 0x35CFFF,
  'glass-tint': 0xEBD9C5,
  'cell-blue': 0x2F58B8,
  'grow-magenta': 0xE040FB,
  'plant-green': 0x5A9E58,
  'ice-pale': 0xD8EEF8
};

const BUDGETS = {"small-prop":1500,"medium-prop":6000,"vehicle":9000,"building":12000,"character":8000,"rock":400};
const SEGMENTS = {"small":8,"default":12,"large":16};

// Bevel radius for roundedBoxGeo: ratio of the smallest dimension (style range 0.06-0.12).
function bevel(w, h, d, ratio = 0.09) {
  return Math.min(w, h, d) * ratio;
}

// One shared material per role. Variants (e.g. structure-gray) take an explicit colour token.
function styleMaterials() {
  const m = {"matte-environment":{"description":"Terrain, rocks, craters, mountains. Fully matte, no reflections.","colors":["regolith-mid","regolith-light","shadow-plum"],"roughness":0.95,"metalness":0},"smooth-structure":{"description":"Buildings, modules, vehicles, suits, crates. Clean satin finish, never mirror-like.","colors":["structure-white","structure-gray"],"roughness":0.55,"metalness":0.05},"accent-paint":{"description":"Non-glowing orange colour blocking: side panels, crate faces, dome base band, suit pads, wheel hubs.","colors":["accent-orange"],"roughness":0.6,"metalness":0},"dark-trim":{"description":"Tyres, recesses, joints, vents.","colors":["trim-dark"],"roughness":0.85,"metalness":0},"emissive-warm":{"description":"Door frames, window strips, headlights. Selected surfaces only.","colors":["accent-orange"],"emissive":"accent-orange","emissiveIntensity":1.6,"roughness":0.5,"metalness":0},"emissive-cool":{"description":"Beacons, indicators, screens. Smaller and rarer than warm lights.","colors":["accent-cyan","accent-blue"],"emissive":"accent-cyan","emissiveIntensity":1.4,"roughness":0.5,"metalness":0},"glass":{"description":"Greenhouse domes, module windows. Light tint, soft highlight, see-through.","colors":["glass-tint"],"roughness":0.15,"metalness":0,"opacity":0.35},"visor":{"description":"Helmet visors and vehicle windshields. Opaque near-black, glossy, shows a soft highlight.","colors":["space-deep"],"roughness":0.12,"metalness":0.1},"solar-cell":{"description":"Solar panel cell faces. Deep blue, semi-gloss, framed by structure-white grid bars.","colors":["cell-blue"],"roughness":0.35,"metalness":0.1}};
  const make = (role, colorToken) => {
    const spec = m[role];
    const color = PALETTE[colorToken ?? spec.colors[0]];
    const name = colorToken && colorToken !== spec.colors[0] ? role + ':' + colorToken : role;
    if (role === 'glass') return glassMaterial(color, { opacity: spec.opacity, roughness: spec.roughness, metalness: spec.metalness, name });
    const opts = { roughness: spec.roughness, metalness: spec.metalness, name };
    if (spec.emissive) Object.assign(opts, { emissive: PALETTE[spec.emissive], emissiveIntensity: spec.emissiveIntensity });
    return gameMaterial(color, opts);
  };
  return {
    rock: make('matte-environment'),
    rockLight: make('matte-environment', 'regolith-light'),
    rockShadow: make('matte-environment', 'shadow-plum'),
    panel: make('smooth-structure'),
    panelGray: make('smooth-structure', 'structure-gray'),
    accent: make('accent-paint'),
    trim: make('dark-trim'),
    glowWarm: make('emissive-warm'),
    glowCool: make('emissive-cool'),
    glowBlue: make('emissive-cool', 'accent-blue'),
    glass: make('glass'),
    visor: make('visor'),
    solarCell: make('solar-cell'),
  };
}
// ---- end style header ----

const meta = {
  name: 'greenhouse-tray',
  role: 'prop',
  reference: 'models and assets images/phase-6/greenhouse-tray.png'
};

function build() {
  const root = createRoot('greenhouse-tray');
  const m = styleMaterials();

  // Custom token for magenta grow light
  const glowMagenta = gameMaterial(PALETTE['grow-magenta'], {
    emissive: PALETTE['grow-magenta'],
    emissiveIntensity: 1.6,
    roughness: 0.5,
    metalness: 0,
    name: 'emissive-magenta'
  });

  // Tray dimensions:
  // Width along Z: 1.60 m (from Z = -0.80 to +0.80)
  // Depth along X: 1.20 m (from X = -0.60 to +0.60, +X is front with orange panel)
  // Tub height: 0.32 m

  // -------------------------------------------------------------------------
  // 1. TRAY OUTER TUB & FOUNDATION (Y = 0 to 0.32)
  // -------------------------------------------------------------------------
  const tubPivot = createPivot('TrayTub', [0, 0, 0], root);
  const tX = 1.16;
  const tZ = 1.56;
  const tY = 0.28;

  // Main dark slate tub body
  createPart('TubBody', boxGeo(tX, tY, tZ), m.panelGray, {
    position: [0, tY / 2, 0],
    parent: tubPivot
  });

  // Corner chamfer bevels for tub
  for (const signX of [1, -1]) {
    for (const signZ of [1, -1]) {
      createPart(`TubCorner_${signX}_${signZ}`, boxGeo(0.18, tY + 0.005, 0.18), m.panelGray, {
        position: [signX * (tX / 2 - 0.05), tY / 2, signZ * (tZ / 2 - 0.05)],
        rotation: [0, 45, 0],
        parent: tubPivot
      });
    }
  }

  // Front orange accent plate (+X face)
  const plateW = 0.96;
  const plateH = 0.20;
  createPart('FrontAccentPlate', boxGeo(0.04, plateH, plateW), m.accent, {
    position: [tX / 2 + 0.015, tY / 2 - 0.01, 0],
    parent: tubPivot
  });

  // Top perimeter rim collar (cream ivory bevel rim)
  const rimThick = 0.14;
  const rimH = 0.07;
  const rimY = tY + rimH / 2; // Y = 0.315

  // Front and back rim bars
  createPart('RimBar_Front', boxGeo(rimThick, rimH, tZ), m.panel, {
    position: [tX / 2 - rimThick / 2, rimY, 0],
    parent: tubPivot
  });
  createPart('RimBar_Back', boxGeo(rimThick, rimH, tZ), m.panel, {
    position: [-tX / 2 + rimThick / 2, rimY, 0],
    parent: tubPivot
  });

  // Left and right rim bars
  createPart('RimBar_Left', boxGeo(tX - rimThick * 2, rimH, rimThick), m.panel, {
    position: [0, rimY, tZ / 2 - rimThick / 2],
    parent: tubPivot
  });
  createPart('RimBar_Right', boxGeo(tX - rimThick * 2, rimH, rimThick), m.panel, {
    position: [0, rimY, -tZ / 2 + rimThick / 2],
    parent: tubPivot
  });

  // Corner rim pads to seamlessly cap the corners
  for (const signX of [1, -1]) {
    for (const signZ of [1, -1]) {
      createPart(`RimCorner_${signX}_${signZ}`, boxGeo(rimThick, rimH, rimThick), m.panel, {
        position: [signX * (tX / 2 - rimThick / 2), rimY, signZ * (tZ / 2 - rimThick / 2)],
        parent: tubPivot
      });
    }
  }

  // Recessed tray interior bed floor (dark blue/trim)
  createPart('InteriorBedFloor', boxGeo(tX - rimThick * 2, 0.04, tZ - rimThick * 2), m.trim, {
    position: [0, tY - 0.02, 0],
    parent: tubPivot
  });

  // -------------------------------------------------------------------------
  // 2. 6 GROWTH-PILLOW SLOTS (2 x 3 Grid)
  // -------------------------------------------------------------------------
  // Grid layout:
  // Row 0 (Rear, near water feed): X = -0.22
  // Row 1 (Front): X = 0.22
  // Columns: Z = -0.44, 0.0, +0.44
  const pillowCols = [-0.44, 0.0, 0.44];
  const pillowRows = [-0.22, 0.22];

  let pillowIndex = 1;
  for (let r = 0; r < 2; r++) {
    for (let c = 0; c < 3; c++) {
      const pX = pillowRows[r];
      const pZ = pillowCols[c];
      const slotPivot = createPivot(`pillow_slot_${pillowIndex}`, [pX, tY, pZ], root);

      // Pillow cushion (soft sand/ivory fabric form)
      const pW = 0.36;
      const pL = 0.36;
      const pH = 0.08;
      // Main rounded pillow body
      createPart(`PillowCushion_${pillowIndex}`, boxGeo(pW, pH, pL), m.panel, {
        position: [0, pH / 2, 0],
        parent: slotPivot
      });

      // Soft pillow edge chamfers
      for (const signX of [1, -1]) {
        for (const signZ of [1, -1]) {
          createPart(`PillowChamfer_${pillowIndex}_${signX}_${signZ}`, boxGeo(0.06, pH + 0.005, 0.06), m.panel, {
            position: [signX * (pW / 2 - 0.025), pH / 2, signZ * (pL / 2 - 0.025)],
            rotation: [0, 45, 0],
            parent: slotPivot
          });
        }
      }

      pillowIndex++;
    }
  }

  // -------------------------------------------------------------------------
  // 3. WATER FEED MANIFOLD & NOZZLES
  // -------------------------------------------------------------------------
  const waterPivot = createPivot('water_feed', [0, 0, 0], root);
  const manifoldX = -0.46;
  const manifoldY = tY + 0.06;

  // Main horizontal manifold pipe along Z
  createPart('ManifoldPipe', cylinderGeo(0.016, 0.016, 1.06, 8), m.panel, {
    position: [manifoldX, manifoldY, 0],
    rotation: [90, 0, 0],
    parent: waterPivot
  });

  // End elbows / mounting brackets on manifold
  createPart('ManifoldElbow_L', boxGeo(0.05, 0.04, 0.04), m.panel, {
    position: [manifoldX, manifoldY, 0.53],
    parent: waterPivot
  });
  createPart('ManifoldElbow_R', boxGeo(0.05, 0.04, 0.04), m.panel, {
    position: [manifoldX, manifoldY, -0.53],
    parent: waterPivot
  });

  // 3 Feed nozzles branching into the rear 3 pillows
  for (let c = 0; c < 3; c++) {
    const nZ = pillowCols[c];
    // T-junction collar
    createPart(`NozzleCollar_${c + 1}`, cylinderGeo(0.022, 0.022, 0.04, 8), m.panel, {
      position: [manifoldX, manifoldY, nZ],
      rotation: [90, 0, 0],
      parent: waterPivot
    });
    // Pipe nozzle running forward and down into pillow
    createPart(`NozzleFeed_${c + 1}`, boxGeo(0.12, 0.022, 0.022), m.panel, {
      position: [manifoldX + 0.06, manifoldY, nZ],
      parent: waterPivot
    });
    createPart(`NozzleDrop_${c + 1}`, cylinderGeo(0.011, 0.011, 0.035, 8), m.panel, {
      position: [manifoldX + 0.12, manifoldY - 0.018, nZ],
      parent: waterPivot
    });
  }

  // -------------------------------------------------------------------------
  // 4. OVERHEAD LED CANOPY & VERTICAL REAR MAST
  // -------------------------------------------------------------------------
  const canopyPivot = createPivot('led_cap', [0, 0, 0], root);

  // Rear vertical mast base socket
  const mastX = -0.54;
  createPart('MastBaseSocket', boxGeo(0.20, 0.12, 0.22), m.panelGray, {
    position: [mastX, tY + 0.05, 0],
    parent: canopyPivot
  });

  // Central vertical mast column
  const mastH = 0.52;
  createPart('MastColumn', boxGeo(0.14, mastH, 0.16), m.panelGray, {
    position: [mastX, tY + 0.10 + mastH / 2, 0],
    parent: canopyPivot
  });

  // Top mast cap / extension post
  createPart('MastTopPost', boxGeo(0.12, 0.16, 0.14), m.panelGray, {
    position: [mastX, tY + 0.10 + mastH + 0.08, 0],
    parent: canopyPivot
  });

  // Horizontal cantilever arm extending forward to CENTER of tray (X = 0)
  const canopyArmY = tY + 0.10 + mastH - 0.05; // Y = 0.89
  const armLen = 0.52;
  createPart('CanopyCantilever', boxGeo(armLen, 0.12, 0.16), m.panelGray, {
    position: [mastX + armLen / 2 + 0.06, canopyArmY, 0],
    parent: canopyPivot
  });

  // Overhead LED canopy hood housing (slate grey faceted hood)
  // Perfectly centered over tray at X = 0, Z = 0
  const hoodW = 0.44;
  const hoodH = 0.14;
  const hoodL = 1.16;
  const hoodX = 0.0;
  const hoodY = canopyArmY;

  createPart('HoodMain', boxGeo(hoodW, hoodH, hoodL), m.panelGray, {
    position: [hoodX, hoodY, 0],
    parent: canopyPivot
  });

  // Chamfered edges on canopy hood
  for (const signX of [1, -1]) {
    createPart(`HoodChamferX_${signX}`, boxGeo(0.08, 0.08, hoodL + 0.005), m.panelGray, {
      position: [hoodX + signX * (hoodW / 2 - 0.03), hoodY + 0.04, 0],
      rotation: [0, 0, signX * 45],
      parent: canopyPivot
    });
  }
  for (const signZ of [1, -1]) {
    createPart(`HoodChamferZ_${signZ}`, boxGeo(hoodW + 0.005, 0.08, 0.08), m.panelGray, {
      position: [hoodX, hoodY + 0.04, signZ * (hoodL / 2 - 0.03)],
      rotation: [signZ * 45, 0, 0],
      parent: canopyPivot
    });
  }

  // Underside recessed glowing magenta LED strip (semantic 'led_light' node)
  const lightPivot = createPivot('led_light', [hoodX, hoodY - hoodH / 2 - 0.005, 0], canopyPivot);
  createPart('MagentaLEDStrip', boxGeo(hoodW * 0.78, 0.02, hoodL * 0.88), glowMagenta, {
    position: [0, 0, 0],
    parent: lightPivot
  });

  // Define Category Budget
  defineBudget({ triangles: BUDGETS['medium-prop'] }, root);

  return root;
}
